-- RuSQL 전시 시연용 데이터 (docs/mds/EXHIBITION.md). SQL 편집기에 통째로 붙여 넣고 Run All 한 번이면 끝난다(처음 한 번만: expo 데이터베이스가 이미 있으면 CREATE DATABASE가 실패한다).
-- 표 3개: customers 300행, orders 1,500행(customers를 가리키는 외래키), logs 131,072행(인덱스 시연용 큰 표).
CREATE DATABASE expo;
USE expo;
CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30), city VARCHAR(20));
CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, status VARCHAR(10), total INT, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE logs (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT, action VARCHAR(10), amount INT);
-- 아래 17줄은 같은 문장이다: 행 수를 두 배씩 늘려 131,072행을 만든다.
